<!-- Generated by svelte-trisql-scaffold for posts. Edit freely. -->
<script lang="ts">
	import { goto } from '$app/navigation';
	import { page } from '$app/state';
	import { deletePost, getPost, updatePost } from '#lib/posts.remote.ts';

	const row = $derived(await getPost(page.params.id ?? ''));

	// 現在値をフォームに入れる
	$effect(() => {
		if (!row) return;
		updatePost.fields.set({
			id: String(row.id),
			user_id: row.user_id == null ? '' : String(row.user_id),
			title: row.title == null ? '' : String(row.title),
			body: row.body == null ? '' : String(row.body),
			published: row.published ?? false,
		});
	});

	async function remove() {
		if (!row) return;
		await deletePost(row.id);
		await goto('/posts');
	}
</script>

{#if row}
	<h1>post {row.id}</h1>
	<form {...updatePost}>
		<input {...updatePost.fields.id.as('hidden', String(row.id))} />
		<label>user_id <input {...updatePost.fields.user_id.as('text')} /></label>
		{#each updatePost.fields.user_id.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<label>title <input {...updatePost.fields.title.as('text')} /></label>
		{#each updatePost.fields.title.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<label>body <input {...updatePost.fields.body.as('text')} /></label>
		{#each updatePost.fields.body.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<label><input {...updatePost.fields.published.as('checkbox')} /> published</label>
		{#each updatePost.fields.published.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<button>Save</button>
	</form>
	<button onclick={remove}>Delete</button>
{:else}
	<p>Not found.</p>
{/if}
<p><a href="/posts">Back to posts</a></p>
